def test_basic_devices():
    """Test different PennyLane devices for CPU performance."""
    print("=== Testing PennyLane Devices ===")

    devices = {
        'default.qubit': 'Standard simulator',
        'lightning.qubit': 'C++ Lightning simulator (if available)', 
        'default.mixed': 'Mixed state simulator'
    }

    results = {}

    for device_name, description in devices.items():
        try:
            print(f"\n🔧 Testing {device_name}: {description}")

            # Create device
            dev = qml.device(device_name, wires=4)

            @qml.qnode(dev)
            def test_circuit():
                # Create Bell state + extra entanglement
                qml.Hadamard(wires=0)
                qml.CNOT(wires=[0, 1])
                qml.Hadamard(wires=2)  
                qml.CNOT(wires=[2, 3])
                qml.CNOT(wires=[1, 2])  # Cross-entangle
                return qml.probs(wires=[0, 1, 2, 3])

            # Time the execution
            start_time = time.perf_counter()
            for _ in range(10):  # Run multiple times
                result = test_circuit()
            execution_time = (time.perf_counter() - start_time) / 10

            results[device_name] = {
                'time': execution_time,
                'result_shape': result.shape,
                'working': True
            }

            print(f"  ✅ Average execution time: {execution_time:.4f}s")
            print(f"  📊 Result shape: {result.shape}")

        except Exception as e:
            print(f"  ❌ Device {device_name} failed: {e}")
            results[device_name] = {'working': False, 'error': str(e)}

    return results

