import numpy as np
import pennylane as qml

def process_quantum_data(data, look_back, n_qubits, weights):
    quantum_data = []
    for x in data:
        batch_data = np.array_split(x.flatten(), look_back // n_qubits)
        batch_output = [quantum_circuit(batch, weights) for batch in batch_data]
        quantum_data.append(np.concatenate(batch_output))
    return np.array(quantum_data)

def quantum_circuit(batch, weights):
    dev = qml.device('default.qubit', wires=len(batch))

    @qml.qnode(dev)
    def circuit(inputs, weights):
        for i, x in enumerate(inputs):
            qml.RX(x, wires=i)
        qml.templates.StronglyEntanglingLayers(weights, wires=range(len(inputs)))
        return [qml.expval(qml.PauliZ(w)) for w in range(len(inputs))]

    return circuit(batch, weights)

