import numpy as np

def run(test_case_input: str) -> str:
    params, shift = json.loads(test_case_input)
    gradient = my_parameter_shift_grad(params, shift)
    return str(gradient)

def my_parameter_shift_grad(params, shift):
    dev = qml.device('default.qubit', wires=1)

    @qml.qnode(dev)
    def circuit(params):
        qml.RY(params[0], wires=0)
        return qml.expval(qml.PauliZ(0))

    def parameter_shift(params, shift_idx):
        shifted_params_plus = params.copy()
        shifted_params_minus = params.copy()

        shifted_params_plus[shift_idx] += shift
        shifted_params_minus[shift_idx] -= shift

        grad = (circuit(shifted_params_plus) - circuit(shifted_params_minus)) / (2 * np.sin(shift))
        return grad

    return parameter_shift(params, shift)

