dev = qml.device('default.qubit', shots=1000)

def ex_jc_circuit():
    @qml.qnode(dev)
    def circuit(n):
        for j in range(n):
            qml.PauliX(wires=0)
            qml.RY(np.pi / (2 * np.sqrt(j + 1)), wires=1)
            qml.CNOT(wires=[0, 1])

        return qml.expval(qml.PauliZ(1))

    n = 5
    fig, ax = qml.draw(circuit)(n)
