from pennylane import numpy as np
import pennylane as qml

def distance(A, B):
    dev = qml.device("default.qubit", wires=1)
    @qml.qnode(dev)
    def get_state(base_state):
        qml.AmplitudeEmbedding(base_state, wires=0, normalize=True)
        return qml.state()

    A = get_state(A)
    B = get_state(B)
    return np.sqrt(2*(1-np.inner(A,np.conj(B))).real)

import pennylane as qml
from pennylane import numpy as np

N_WIRES = 4
N_OUTPUT = 3

dev = qml.device("default.qubit", wires=N_WIRES)

@qml.qnode(dev)
def circuit(phi, filter):
    for j in range(len(phi)):
        qml.RY(np.pi*phi[j], wires=j)

    if filter == 1:
        for i in range(len(phi)):
            qml.Hadamard(i)
    elif filter == 2:
        qml.RY(np.pi/2*0.3, wires=1)
    elif filter == 3:
        for i in range(len(phi)):
            qml.Hadamard(i)
            qml.RY(np.pi*0.3, wires=0)
    elif filter == 4:
        for i in range(len(phi)):
            qml.CNOT(wires=[0,1])
            qml.CNOT(wires=[2,3])

    return [qml.expval(qml.PauliZ(j)) for j in range(len(phi))]

