import torch
import pennylane as qml
import numpy as np

def quantum_embedding_zz(x):
    dev = qml.device('default.qubit', wires=len(x))

    @qml.qnode(dev)
    def circuit(x):
        for i in range(len(x)):
            qml.RY(x[i], wires=i)
        return [qml.expval(qml.PauliZ(wire)) for wire in range(len(x))]

    return circuit(x)

def quantum_embedding_rl(x, action_seq):
    dev = qml.device('default.qubit', wires=len(x))

    @qml.qnode(dev)
    def circuit(x, action_seq):
        for i in range(len(x)):
            qml.RY(x[i], wires=i)
        for action in action_seq:
            qml.CNOT(wires=[action[0], action[1]])
        return [qml.expval(qml.PauliZ(wire)) for wire in range(len(x))]

    return circuit(x, action_seq)

def statepreparation(x, scheme, NQE_model=None, action_seq=None):
    if scheme is None:
        return quantum_embedding_zz(x)
    elif scheme == 'NQE':
        x = NQE_model.linear_relu_stack1(torch.tensor(x, dtype=torch.float32))
        x = x.detach().numpy()
        return quantum_embedding_zz(x)
    elif scheme == 'NQE_RL':
        x = NQE_model.linear_relu_stack1(torch.tensor(x, dtype=torch.float32))
        x = x.detach().numpy()
        return quantum_embedding_rl(x, action_seq)

