import jax
import jax.numpy as jnp

def value_and_grad(fn=None, *, method=None, h=None, argnums=None):
    if fn is None:
        return lambda f: value_and_grad(f, method=method, h=h, argnums=argnums)

    def wrapper(*args, **kwargs):
        if method == "fd":
            step = h if h is not None else 1e-7
            value = fn(*args, **kwargs)

            grad_args = argnums if argnums is not None else 0
            if isinstance(grad_args, int):
                grad_args = [grad_args]

            grads = []
            for argnum in grad_args:
                args_list = list(args)
                original = args_list[argnum]

                if isinstance(original, (int, float)):
                    args_plus = args_list.copy()
                    args_plus[argnum] = original + step
                    val_plus = fn(*args_plus, **kwargs)
                    grad = (val_plus - value) / step
                else:
                    grad = np.zeros_like(original)
                    for i in range(len(original)):
                        args_plus = args_list.copy()
                        temp = original.copy()
                        temp[i] += step
                        args_plus[argnum] = temp
                        val_plus = fn(*args_plus, **kwargs)
                        grad[i] = (val_plus - value) / step

                grads.append(grad)

            return value, grads[0] if len(grads) == 1 else tuple(grads)
        else:
            return jax.value_and_grad(fn, argnums=argnums)(*args, **kwargs)

    return wrapper

