import pennylane as qml
from pennylane import numpy as np
import jax

def jacobian(fn=None, *, method=None, h=None, argnums=None):
    if fn is None:
        return lambda f: jacobian(f, method=method, h=h, argnums=argnums)

    if method is None:
        method = "auto"

    if method == "auto":
        return jax.jacobian(fn, argnums=argnums)
    elif method == "fd":
        def finite_diff_jacobian(*args, **kwargs):
            step = h if h is not None else 1e-7
            result = fn(*args, **kwargs)

            if argnums is None:
                target_argnums = list(range(len(args)))
            elif isinstance(argnums, int):
                target_argnums = [argnums]
            else:
                target_argnums = list(argnums)

            jac = []
            for argnum in target_argnums:
                arg_jac = []
                arg_array = np.array(args[argnum])
                for i in range(len(arg_array.flatten())):
                    args_plus = list(args)
                    args_plus[argnum] = arg_array.copy()
                    args_plus[argnum].flatten()[i] += step
                    result_plus = fn(*args_plus, **kwargs)

                    grad = (result_plus - result) / step
                    arg_jac.append(grad)
                jac.append(np.array(arg_jac))

            return jac[0] if len(jac) == 1 else jac

        return finite_diff_jacobian
    else:
        raise ValueError(f"Unknown method: {method}")

