import pennylane as qml
import numpy as np
from pennylane.measurements import Counts

def measurements_from_counts(tape):
    if not tape.shots:
        return [tape], lambda x: x[0]

    new_measurements = [qml.counts()]

    def processing_fn(results):
        counts = results[0]
        processed_results = []

        for mp in tape.measurements:
            if isinstance(mp, qml.measurements.ExpectationMP):
                expectation = sum(
                    count * mp.eigvals()[int(outcome, 2)]
                    for outcome, count in counts.items()
                ) / sum(counts.values())
                processed_results.append(expectation)
            elif isinstance(mp, qml.measurements.ProbabilityMP):
                total_shots = sum(counts.values())
                probs = {outcome: count / total_shots for outcome, count in counts.items()}
                processed_results.append(probs)
            elif isinstance(mp, qml.measurements.SampleMP):
                samples = []
                for outcome, count in counts.items():
                    samples.extend([int(outcome, 2)] * count)
                processed_results.append(np.array(samples))
            else:
                processed_results.append(counts)

        return processed_results if len(processed_results) > 1 else processed_results[0]

    new_tape = qml.tape.QuantumScript(
        tape.operations,
        new_measurements,
        shots=tape.shots
    )

    return [new_tape], processing_fn

