import pennylane as qml
import numpy as np
from pennylane.measurements import SampleMP, CountsMP, ExpvalMP, VarMP, ProbabilityMP
from pennylane.tape import QuantumTape

@qml.transform
def measurements_from_samples(tape):
    if tape.shots is None:
        return (tape,), lambda x: x[0]

    measurements = tape.measurements
    if not measurements:
        return (tape,), lambda x: x[0]

    obs_list = [m.obs for m in measurements if hasattr(m, 'obs') and m.obs is not None]

    if obs_list:
        diagonalizing_gates = qml.pauli.diagonalize_qwc_pauli_words(obs_list)[0]
    else:
        diagonalizing_gates = []

    new_operations = tape.operations + diagonalizing_gates
    new_measurements = [qml.sample(wires=tape.wires)]

    new_tape = QuantumTape(new_operations, new_measurements, shots=tape.shots)

    def processing_fn(results):
        samples = results[0]
        processed_results = []

        for m in measurements:
            if isinstance(m, SampleMP):
                if m.obs is None:
                    processed_results.append(samples)
                else:
                    eigvals = m.obs.eigvals()
                    wires_map = {w: i for i, w in enumerate(tape.wires)}
                    obs_wires = [wires_map[w] for w in m.obs.wires]
                    processed_results.append(eigvals[samples[:, obs_wires]])

            elif isinstance(m, CountsMP):
                if m.obs is None:
                    unique, counts = np.unique(samples, axis=0, return_counts=True)
                    processed_results.append(dict(zip(map(tuple, unique), counts)))
                else:
                    eigvals = m.obs.eigvals()
                    wires_map = {w: i for i, w in enumerate(tape.wires)}
                    obs_wires = [wires_map[w] for w in m.obs.wires]
                    obs_samples = eigvals[samples[:, obs_wires]]
                    unique, counts = np.unique(obs_samples, return_counts=True)
                    processed_results.append(dict(zip(unique, counts)))

            elif isinstance(m, ExpvalMP):
                eigvals = m.obs.eigvals()
                wires_map = {w: i for i, w in enumerate(tape.wires)}
                obs_wires = [wires_map[w] for w in m.obs.wires]
                obs_samples = eigvals[samples[:, obs_wires]]
                processed_results.append(np.mean(obs_samples))

            elif isinstance(m, VarMP):
                eigvals = m.obs.eigvals()
                wires_map = {w: i for i, w in enumerate(tape.wires)}
                obs_wires = [wires_map[w] for w in m.obs.wires]
                obs_samples = eigvals[samples[:, obs_wires]]
                processed_results.append(np.var(obs_samples))

            elif isinstance(m, ProbabilityMP):
                if m.wires:
                    wires_map = {w: i for i, w in enumerate(tape.wires)}
                    prob_wires = [wires_map[w] for w in m.wires]
                    sub_samples = samples[:, prob_wires]
                else:
                    sub_samples = samples
                unique, counts = np.unique(sub_samples, axis=0, return_counts=True)
                probs = counts / len(samples)
                processed_results.append(probs)

        return tuple(processed_results) if len(processed_results) > 1 else processed_results[0]

    return [new_tape], processing_fn

