from typing import Callable, Sequence, Union, Optional, List
from numpy.random import SeedSequence, BitGenerator, Generator

def sample_state(
    state,
    shots: int,
    is_state_batched: bool = False,
    wires=None,
    rng=None,
    prng_key=None,
    readout_errors: List[Callable] = None,
) -> np.ndarray:
    if prng_key is not None:
        import jax
        from jax import random

        num_wires = len(wires) if wires is not None else int(np.log2(len(state)))
        probs = np.abs(state) ** 2

        if is_state_batched:
            samples = np.array([random.choice(prng_key, len(probs[i]), shape=(shots,), p=probs[i]) for i in range(len(state))])
        else:
            samples = random.choice(prng_key, len(probs), shape=(shots,), p=probs)
            samples = np.array([list(map(int, format(s, f'0{num_wires}b'))) for s in samples])

        if readout_errors is not None:
            for wire_idx, channel in enumerate(readout_errors):
                if channel is not None:
                    samples[:, wire_idx] = channel(samples[:, wire_idx])

        return samples

    rng = np.random.default_rng(rng)
    num_wires = len(wires) if wires is not None else int(np.log2(len(state)))
    probs = np.abs(state) ** 2

    if is_state_batched:
        samples = np.array([rng.choice(len(probs[i]), size=shots, p=probs[i]) for i in range(len(state))])
    else:
        samples = rng.choice(len(probs), size=shots, p=probs)
        samples = np.array([list(map(int, format(s, f'0{num_wires}b'))) for s in samples])

    if readout_errors is not None:
        for wire_idx, channel in enumerate(readout_errors):
            if channel is not None:
                samples[:, wire_idx] = channel(samples[:, wire_idx])

    return samples

