import pennylane as qml
from pennylane.resource import Resources, ResourceConfig, ResourceOperator
from typing import Callable, QNode

def estimate(
    workflow: Callable | ResourceOperator | Resources | QNode,
    gate_set: set[str] | None = None,
    zeroed_wires: int = 0,
    any_state_wires: int = 0,
    tight_wires_budget: bool = False,
    config: ResourceConfig | None = None,
) -> Resources | Callable[..., Resources]:

    if gate_set is None:
        gate_set = {'Toffoli', 'T', 'CNOT', 'X', 'Y', 'Z', 'S', 'Hadamard'}

    if config is None:
        config = ResourceConfig()

    if isinstance(workflow, Resources):
        return workflow

    if isinstance(workflow, ResourceOperator):
        return workflow.resources(gate_set=gate_set)

    if isinstance(workflow, QNode):
        return qml.specs(workflow, level="device")

    def wrapper(*args, **kwargs):
        result = workflow(*args, **kwargs)
        return qml.resource.estimate_resources(
            result,
            gate_set=gate_set,
            zeroed_wires=zeroed_wires,
            any_state_wires=any_state_wires,
            tight_wires_budget=tight_wires_budget,
            config=config
        )

    return wrapper


