import pennylane as qml
import numpy as np
from functools import wraps

def reduce_t_depth(qnode):
    @wraps(qnode)
    def wrapper(*args, **kwargs):
        original_tape = qnode.qtape if hasattr(qnode, 'qtape') else None

        if original_tape is None:
            qnode(*args, **kwargs)
            original_tape = qnode.qtape

        operations = original_tape.operations

        layers = []
        current_layer = []

        for op in operations:
            if len(current_layer) == 0:
                current_layer.append(op)
            else:
                commutes_with_all = all(
                    qml.is_commuting(op, layer_op) for layer_op in current_layer
                )
                if commutes_with_all:
                    current_layer.append(op)
                else:
                    layers.append(current_layer)
                    current_layer = [op]

        if current_layer:
            layers.append(current_layer)

        optimized_ops = []
        for layer in layers:
            merged = []
            for op in layer:
                if not merged:
                    merged.append(op)
                else:
                    added = False
                    for i, m_op in enumerate(merged):
                        if (type(op) == type(m_op) and 
                            hasattr(op, 'wires') and hasattr(m_op, 'wires') and
                            op.wires == m_op.wires):
                            merged[i] = op
                            added = True
                            break
                    if not added:
                        merged.append(op)
            optimized_ops.extend(merged)

        return qnode(*args, **kwargs)

    return wrapper

