import pennylane as qml
import numpy as np
from typing import Callable, Sequence, Union, Optional, List
from numpy.random import SeedSequence, BitGenerator, Generator

def _get_num_wires(state, is_state_batched):
    num_qubits = int(np.log2(len(state.flatten()) if is_state_batched else len(state))) // 2
    return num_qubits

def sample_state(
    state,
    shots: int,
    is_state_batched: bool = False,
    wires=None,
    rng=None,
    prng_key=None,
    readout_errors: List[Callable] = None,
) -> np.ndarray:
    total_indices = _get_num_wires(state, is_state_batched)

    if wires is None:
        wires = range(total_indices)

    num_wires = len(wires)

    if rng is None:
        rng = np.random.default_rng()
    elif not isinstance(rng, np.random.Generator):
        rng = np.random.default_rng(rng)

    if len(state.shape) == 1:
        state = np.outer(state, np.conj(state))

    probs = np.real(np.diag(state))
    probs = probs / np.sum(probs)

    samples = rng.choice(len(probs), size=shots, p=probs)

    basis_samples = np.zeros((shots, num_wires), dtype=int)
    for i, sample in enumerate(samples):
        binary = format(sample, f'0{total_indices}b')
        basis_samples[i] = [int(binary[w]) for w in wires]

    if readout_errors is not None:
        for wire_idx, channel in enumerate(readout_errors):
            if channel is not None:
                for shot_idx in range(shots):
                    basis_samples[shot_idx, wire_idx] = channel(basis_samples[shot_idx, wire_idx])

    return basis_samples

