from pennylane.tape import QuantumScript, QuantumScriptBatch
from pennylane.transforms import transform
from typing import Callable, tuple

@transform
def validate_measurements(
    tape: QuantumScript, 
    analytic_measurements: Callable = None, 
    sample_measurements: Callable = None, 
    name: str = "device"
) -> tuple[QuantumScriptBatch, Callable]:

    if analytic_measurements is None:
        analytic_measurements = lambda m: True
    if sample_measurements is None:
        sample_measurements = lambda m: True

    for m in tape.measurements:
        if tape.shots:
            if not sample_measurements(m):
                raise qml.DeviceError(
                    f"Measurement {m} not supported on {name} with finite shots"
                )
        else:
            if not analytic_measurements(m):
                raise qml.DeviceError(
                    f"Measurement {m} not supported on {name} in analytic mode"
                )

    return [tape], lambda x: x[0]


