import pennylane as qml
from pennylane.transforms import transform
from typing import Callable

class DeviceCapabilities:
    pass

@transform
def catalyst_decompose(
    tape: qml.tape.QuantumTape, ctx, capabilities: DeviceCapabilities, grad_method: str = None
):
    def stopping_condition(op):
        return op.name in capabilities.supported_ops

    def decompose_op(op):
        if stopping_condition(op):
            return [op]
        decomposition = op.decomposition()
        result = []
        for sub_op in decomposition:
            result.extend(decompose_op(sub_op))
        return result

    new_ops = []
    for op in tape.operations:
        if isinstance(op, qml.StatePrep) or isinstance(op, qml.BasisState):
            new_ops.append(op)
        else:
            new_ops.extend(decompose_op(op))

    new_tape = qml.tape.QuantumScript(new_ops, tape.measurements, shots=tape.shots)

    return [new_tape], lambda x: x[0]

