@transform
def validate_observables(
    tape: QuantumScript,
    stopping_condition: Callable[[Operator], bool],
    stopping_condition_shots: Callable[[Operator], bool] | None = None,
    name: str = "device",
) -> tuple[QuantumScriptBatch, PostprocessingFn]:

    if stopping_condition_shots is not None and tape.shots:
        condition = stopping_condition_shots
    else:
        condition = stopping_condition

    for m in tape.measurements:
        if hasattr(m, 'obs') and m.obs is not None:
            if not condition(m.obs):
                raise qml.DeviceError(
                    f"Observable {m.obs.name} not supported on {name}"
                )

    def processing_fn(tapes):
        return tapes[0]

    return [tape], processing_fn

