import pennylane as qml
import numpy as np
from typing import Callable, Sequence, Union, Optional, List
from numpy.random import SeedSequence, BitGenerator, Generator

def sample_state(
    state,
    shots: int,
    is_state_batched: bool = False,
    wires=None,
    rng=None,
    prng_key=None,
    readout_errors: List[Callable] = None,
) -> np.ndarray:

    if prng_key is not None:
        import jax
        from jax import random

        num_wires = len(wires) if wires is not None else int(np.log2(len(state)))
        probs = np.abs(state) ** 2

        if is_state_batched:
            samples = []
            for batch_probs in probs:
                batch_samples = random.choice(
                    prng_key, 
                    len(batch_probs), 
                    shape=(shots,), 
                    p=batch_probs
                )
                samples.append(batch_samples)
            return np.array(samples)
        else:
            indices = random.choice(prng_key, len(probs), shape=(shots,), p=probs)
            samples = np.array([[int(x) for x in format(idx, f'0{num_wires}b')] for idx in indices])

            if readout_errors is not None:
                for wire_idx, error_channel in enumerate(readout_errors):
                    if error_channel is not None:
                        samples[:, wire_idx] = error_channel(samples[:, wire_idx])

            return samples

    else:
        if rng is None:
            rng = np.random.default_rng()
        elif not isinstance(rng, np.random.Generator):
            rng = np.random.default_rng(rng)

        num_wires = len(wires) if wires is not None else int(np.log2(len(state)))
        probs = np.abs(state) ** 2

        if is_state_batched:
            samples = []
            for batch_probs in probs:
                batch_samples = rng.choice(len(batch_probs), size=shots, p=batch_probs)
                samples.append(batch_samples)
            return np.array(samples)
        else:
            indices = rng.choice(len(probs), size=shots, p=probs)
            samples = np.array([[int(x) for x in format(idx, f'0{num_wires}b')] for idx in indices])

            if readout_errors is not None:
                for wire_idx, error_channel in enumerate(readout_errors):
                    if error_channel is not None:
                        samples[:, wire_idx] = error_channel(samples[:, wire_idx])

            return samples

