import pennylane as qml
import numpy as np
from typing import Sequence, Callable, List, Optional, Dict, Any

def batch_jvp(tapes: Sequence[qml.tape.QuantumTape], 
               tangents: Sequence[Any], 
               gradient_fn: Callable, 
               reduction: str = "append", 
               gradient_kwargs: Optional[Dict] = None) -> List[Optional[Any]]:

    if gradient_kwargs is None:
        gradient_kwargs = {}

    jvps = []

    for tape, tangent in zip(tapes, tangents):
        grad_tapes, processing_fn = gradient_fn(tape, **gradient_kwargs)

        gradients = qml.execute(grad_tapes, tape.device, gradient_fn=None)
        jacobian = processing_fn(gradients)

        if jacobian is None:
            jvps.append(None)
        else:
            jvp = np.tensordot(jacobian, tangent, axes=[[-1], [0]])
            jvps.append(jvp)

    if reduction == "extend":
        extended_jvps = []
        for jvp in jvps:
            if jvp is not None:
                if isinstance(jvp, (list, tuple)):
                    extended_jvps.extend(jvp)
                else:
                    extended_jvps.append(jvp)
        return extended_jvps

    return jvps


