def trace_basis_state(op, qrp):
    assert isinstance(op, qml.BasisState), "qml.BasisState expected"

    qubits = qrp.extract(op.wires)
    basis_state = jax.lax.convert_element_type(op.parameters[0], jnp.dtype(jnp.bool))
    qubits2 = set_basis_state_p.bind(*qubits, basis_state)
    qrp.insert(op.wires, qubits2)

class QRegPromise:
    def __init__(self, num_wires):
        self.qubits = {i: None for i in range(num_wires)}

    def extract(self, wires):
        return [self.qubits[w] for w in wires]

    def insert(self, wires, qubits):
        if isinstance(qubits, list):
            for w, q in zip(wires, qubits):
                self.qubits[w] = q
        else:
            for w in wires:
                self.qubits[w] = qubits

set_basis_state_p = jax.core.Primitive('set_basis_state')

