import pennylane as qml
import numpy as np

def batch_vjp(tapes, dys, gradient_fn, reduction="append", gradient_kwargs=None):
    if gradient_kwargs is None:
        gradient_kwargs = {}

    vjp_tapes = []
    processing_fns = []

    for tape, dy in zip(tapes, dys):
        vjp_tape, processing_fn = qml.gradients.vjp(tape, dy, gradient_fn, **gradient_kwargs)
        vjp_tapes.extend(vjp_tape)
        processing_fns.append(processing_fn)

    def processing_fn(results):
        vjps = []
        start = 0
        for fn in processing_fns:
            num_tapes = len(fn.__code__.co_consts) if hasattr(fn, '__code__') else 1
            vjp = fn(results[start:start + num_tapes])
            vjps.append(vjp)
            start += num_tapes

        if reduction == "append":
            return vjps
        elif reduction == "extend":
            return [item for sublist in vjps for item in sublist]
        elif reduction == "sum":
            return sum(vjps)
        else:
            return vjps

    return vjp_tapes, processing_fn


def example_usage():
    dev = qml.device('default.qubit', wires=2)

    @qml.qnode(dev)
    def circuit(params):
        qml.RX(params[0], wires=0)
        qml.RY(params[1], wires=1)
        qml.CNOT(wires=[0, 1])
        return qml.expval(qml.PauliZ(0))

    params = np.array([0.1, 0.2])
    tape = qml.tape.QuantumTape()
    with tape:
        qml.RX(params[0], wires=0)
        qml.RY(params[1], wires=1)
        qml.CNOT(wires=[0, 1])
        qml.expval(qml.PauliZ(0))

    tapes = [tape]
    dys = [np.array([1.0])]

    vjp_tapes, processing_fn = batch_vjp(tapes, dys, qml.gradients.param_shift)

    return vjp_tapes, processing_fn

