return qml.state()

@qml.qnode(dev, interface=interface, diff_method="backprop")
def circuit2(param):
qml.RY(param, wires=0)
qml.CNOT(wires=[0, 1])
return qml.state()

expected = [
np.sin(param[0] / 2)
* np.cos(param[0] / 2)
* (np.log(np.tan(param[0] / 2) ** 2) - np.log(np.tan(param[1] / 2) ** 2)),
np.cos(param[0] / 2) ** 2 * np.tan(param[1] / 2)
- np.sin(param[0] / 2) ** 2 / np.tan(param[1] / 2),
]

