2
* eig_1
* (np.sin(param / 2) ** 3 * np.cos(param / 2) - np.sin(param / 2) * np.cos(param / 2) ** 3)
/ np.sqrt(1 - 4 * np.sin(param / 2) ** 2 * np.cos(param / 2) ** 2)
) + (
2
* eig_2
* (
np.sin(param / 2)
* np.cos(param / 2)
* (np.cos(param / 2) ** 2 - np.sin(param / 2) ** 2)
)
/ np.sqrt(1 - 4 * np.sin(param / 2) ** 2 * np.cos(param / 2) ** 2)
)
return grad_expected_purity


