from textwrap import dedent

import numpy as np
import pytest

import pennylane as qml
from pennylane.wires import Wires


class TestToQasmUnitTests:
"""Unit tests for the to_openqasm() method"""

def test_empty_circuit(self):
"""Test that an empty circuit graph is properly
serialized into an empty QASM program."""
circuit = qml.tape.QuantumScript()
res = circuit.to_openqasm()
expected = 'OPENQASM 2.0;\ninclude "qelib1.inc";\n'
assert res == expected

def test_native_qasm_gates(self):
"""Test that a circuit containing solely native QASM
gates is properly serialized."""
with qml.queuing.AnnotatedQueue() as q_circuit:
qml.RX(0.43, wires=0)
qml.RY(0.35, wires=1)
qml.RZ(0.35, wires=2)
qml.CNOT(wires=[0, 1])
qml.Hadamard(wires=2)
qml.CNOT(wires=[2, 0])
qml.PauliX(wires=1)

circuit = qml.tape.QuantumScript.from_queue(q_circuit)
res = circuit.to_openqasm()

expected = dedent(
"""\
OPENQASM 2.0;
include "qelib1.inc";
qreg q[3];
creg c[3];
rx(0.43) q[0];
ry(0.35) q[1];
rz(0.35) q[2];
cx q[0],q[1];
h q[2];
cx q[2],q[0];
x q[1];
measure q[0] -> c[0];
measure q[1] -> c[1];
measure q[2] -> c[2];
"""
)

assert res == expected

def test_unused_wires(self):
"""Test that unused wires are correctly taken into account"""
with qml.queuing.AnnotatedQueue() as q_circuit:
qml.Hadamard(wires=4)
qml.CNOT(wires=[1, 0])

circuit = qml.tape.QuantumScript.from_queue(q_circuit)
res = circuit.to_openqasm(wires=Wires([0, 1, 2, 3, 4]))

expected = dedent(
"""\
OPENQASM 2.0;
include "qelib1.inc";
qreg q[5];
creg c[5];
h q[4];
cx q[1],q[0];
measure q[0] -> c[0];
measure q[1] -> c[1];
measure q[2] -> c[2];
measure q[3] -> c[3];
measure q[4] -> c[4];
"""
)

assert res == expected

def test_to_ApproxTimeEvolution(self):
"""Test for case that requires a decomposition depth of 3 to successfully convert to a MutliRZ"""
H = qml.Hamiltonian(
[
1,
],
[
qml.PauliZ(0) @ qml.PauliZ(1),
],
)
circuit = qml.tape.QuantumScript([qml.ApproxTimeEvolution(H, 1, n=1)])
res = circuit.to_openqasm(wires=Wires([0, 1]))

expected = dedent(
"""\
OPENQASM 2.0;
include "qelib1.inc";
qreg q[2];
creg c[2];
cx q[1],q[0];
rz(2.0) q[0];
cx q[1],q[0];
measure q[0] -> c[0];
measure q[1] -> c[1];
"""
)

assert res == expected

def test_rotation_gate_decomposition(self):
"""Test that gates not natively supported by QASM, such as the
rotation gate, are correctly decomposed and serialized."""
with qml.queuing.AnnotatedQueue() as q1:
qml.Rot(0.3, 0.1, 0.2, wires=1)

circuit1 = qml.tape.QuantumScript.from_queue(q1)
qasm1 = circuit1.to_openqasm(wires=Wires([0, 1]))

with qml.queuing.AnnotatedQueue() as q2:
qml.Rot.compute_decomposition(0.3, 0.1, 0.2, wires=1)

circuit2 = qml.tape.QuantumScript.from_queue(q2)
qasm2 = circuit2.to_openqasm(wires=Wires([0, 1]))

expected = dedent(
"""\
OPENQASM 2.0;
include "qelib1.inc";
qreg q[2];
creg c[2];
rz(0.3) q[1];
ry(0.1) q[1];
rz(0.2) q[1];
measure q[0] -> c[0];
measure q[1] -> c[1];
"""
)

assert qasm1 == expected
assert qasm1 == qasm2

def test_state_initialization_decomposition(self):
"""Test that the Mottonen state prepration decomposition
is correctly applied."""
psi = np.array([1, -1, -1, 1]) / np.sqrt(4)

with qml.queuing.AnnotatedQueue() as q1:
qml.StatePrep(psi, wires=[0, 1])

circuit1 = qml.tape.QuantumScript.from_queue(q1)
qasm1 = circuit1.to_openqasm(precision=11)

with qml.queuing.AnnotatedQueue() as q2:
qml.StatePrep.compute_decomposition(psi, wires=[0, 1])

circuit2 = qml.tape.QuantumScript.from_queue(q2)
qasm2 = circuit2.to_openqasm(wires=Wires([0, 1]), precision=11)

expected = dedent(
"""\
OPENQASM 2.0;
include "qelib1.inc";
qreg q[2];
creg c[2];
ry(1.5707963268) q[0];
ry(1.5707963268) q[1];
cx q[0],q[1];
cx q[0],q[1];
cx q[0],q[1];
rz(3.1415926536) q[1];
cx q[0],q[1];
measure q[0] -> c[0];
measure q[1] -> c[1];
"""
)

# different
assert qasm1 == expected
assert qasm1 == qasm2

def test_basis_state_initialization_decomposition(self):
"""Test that the basis state preparation decomposition
is correctly applied."""
basis_state = np.array([1, 0, 1, 1])

with qml.queuing.AnnotatedQueue() as q1:
qml.BasisState(basis_state, wires=[0, 1, 2, 3])

circuit1 = qml.tape.QuantumScript.from_queue(q1)
qasm1 = circuit1.to_openqasm()

with qml.queuing.AnnotatedQueue() as q2:
qml.BasisState.compute_decomposition(basis_state, wires=[0, 1, 2, 3])

circuit2 = qml.tape.QuantumScript.from_queue(q2)
qasm2 = circuit2.to_openqasm(wires=[0, 1, 2, 3])

expected = dedent(
"""\
OPENQASM 2.0;
include "qelib1.inc";
qreg q[4];
creg c[4];
x q[0];
x q[2];
x q[3];
measure q[0] -> c[0];
measure q[1] -> c[1];
measure q[2] -> c[2];
measure q[3] -> c[3];
"""
)

assert qasm1 == expected
assert qasm1 == qasm2

def test_unsupported_gate(self):
"""Test an exception is raised if an unsupported operation is
applied."""
with qml.queuing.AnnotatedQueue() as q_circuit:
qml.S(wires=0)
qml.DoubleExcitationPlus(0.5, wires=[0, 1, 2, 3])

circuit = qml.tape.QuantumScript.from_queue(q_circuit)
with pytest.raises(
ValueError, match="DoubleExcitationPlus not supported by the QASM serializer"
):
circuit.to_openqasm()

def test_rotations(self):
"""Test that observable rotations are correctly applied."""

with qml.queuing.AnnotatedQueue() as q_circuit:
qml.Hadamard(wires=0)
qml.CNOT(wires=[0, 1])
qml.expval(qml.PauliX(0))
qml.expval(qml.PauliZ(1))
qml.expval(qml.Hadamard(2))

circuit = qml.tape.QuantumScript.from_queue(q_circuit)
res = circuit.to_openqasm()

expected = dedent(
"""\
OPENQASM 2.0;
include "qelib1.inc";
qreg q[3];
creg c[3];
h q[0];
cx q[0],q[1];
h q[0];
ry(-0.7853981633974483) q[2];
measure q[0] -> c[0];
measure q[1] -> c[1];
measure q[2] -> c[2];
"""
)

assert res == expected

ops2 = circuit.operations + circuit.diagonalizing_gates

with qml.queuing.AnnotatedQueue() as q2:
_ = [o.queue() for o in ops2]

circuit2 = qml.tape.QuantumScript.from_queue(q2)
qasm2 = circuit2.to_openqasm()

assert res == qasm2

def test_only_tape_measurements(self):
"""Test that no computational basis measurements are added other
than those already in the tape when ``measure_all=False``."""
with qml.queuing.AnnotatedQueue() as q_circuit:
qml.RX(0.43, wires="a")
qml.RY(0.35, wires="b")
qml.RZ(0.35, wires=2)
qml.CNOT(wires=["a", "b"])
qml.Hadamard(wires=2)
qml.CNOT(wires=[2, "a"])
qml.PauliX(wires="b")
qml.expval(qml.PauliZ("a"))
qml.expval(qml.PauliZ(2))

circuit = qml.tape.QuantumScript.from_queue(q_circuit)
res = circuit.to_openqasm(measure_all=False)

expected = dedent(
"""\
OPENQASM 2.0;
include "qelib1.inc";
qreg q[3];
creg c[3];
rx(0.43) q[0];
ry(0.35) q[1];
rz(0.35) q[2];
cx q[0],q[1];
h q[2];
cx q[2],q[0];
x q[1];
measure q[0] -> c[0];
measure q[2] -> c[2];
"""
)

assert res == expected


