def test_parametrized_native_qasm_gates(self):
"""Test that a QNode containing solely native QASM
gates, as well as input parameters, is properly serialized.
In addition, double check the serialization changes as parameters
are changed."""
dev = qml.device("default.qubit", wires=3)

@qml.qnode(dev)
def qnode(x, y):
qml.RX(x, wires=0)
qml.RY(y[0], wires=1)
qml.RZ(y[1], wires=2)
qml.CNOT(wires=[0, 1])
qml.Hadamard(wires=2)
qml.CNOT(wires=[2, 0])
qml.PauliX(wires=1)
return qml.expval(qml.PauliZ(0))

# execute the QNode with parameters, and serialize
x = np.array(0.5)
y = np.array([0.2, 0.1])
qnode(x, y)

expected = dedent(
"""\
OPENQASM 2.0;
include "qelib1.inc";
qreg q[3];
creg c[3];
rx(0.5) q[0];
ry(0.2) q[1];
rz(0.1) q[2];
cx q[0],q[1];
h q[2];
cx q[2],q[0];
x q[1];
measure q[0] -> c[0];
measure q[1] -> c[1];
measure q[2] -> c[2];
"""
)

res = qnode.qtape.to_openqasm()
assert res == expected

# execute the QNode with new parameters, and serialize again
x2 = np.array(0.1)
y2 = np.array([0.3, 0.2])
qnode(x2, y2)

expected = dedent(
"""\
OPENQASM 2.0;
include "qelib1.inc";
qreg q[3];
creg c[3];
rx(0.1) q[0];
ry(0.3) q[1];
rz(0.2) q[2];
cx q[0],q[1];
h q[2];
cx q[2],q[0];
x q[1];
measure q[0] -> c[0];
measure q[1] -> c[1];
measure q[2] -> c[2];
"""
)

res = qnode.qtape.to_openqasm()
assert res == expected

