@qml.qnode(dev)
def func():
qml.Hadamard(0)
qml.PauliX(1)
qml.PauliZ(2)
return density_matrix(return_wire_order)

density_full = func()

single_states = [[1 / np.sqrt(2), 1 / np.sqrt(2)], [0, 1], [1, 0]]
if len(return_wire_order) == 1:
exp_statevector = np.array(single_states[return_wire_order[0]])
