def test_nested_tapes():
"""Test nested tapes inside the qnode."""

@qml.qnode(qml.device("default.qubit", wires=1))
def circuit():
with qml.tape.QuantumTape() as tape1:
qml.PauliX(0)
with qml.tape.QuantumTape() as tape2:
