[-0.5 * jnp.sin(a) * (jnp.cos(b) + 1), 0.5 * jnp.sin(b) * (1 - jnp.cos(a))]
)

assert jnp.allclose(jnp.array(res), jnp.array(expected_grad), atol=tol, rtol=0)

